using DSWI_T1_1.Dtos;using DSWI_T1_1.Services.Interfaces;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.Rendering;namespace DSWI_T1_1.Controllers;public class CitasController:Controller{private readonly ICitaService c;private readonly IPacienteService p;public CitasController(ICitaService a,IPacienteService b){c=a;p=b;}public async Task<IActionResult> Index(){var lista=await c.ObtenerTodosAsync();var ps=await p.ObtenerTodosAsync();foreach(var x in lista)x.NombrePaciente=ps.FirstOrDefault(y=>y.PacienteID==x.PacienteID)?.Nombre;return View(lista);}[HttpGet]public async Task<IActionResult> Create(){await Cargar();return View(new CitaDto{Fecha=DateTime.Today,Hora=new TimeSpan(9,0,0)});}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Create(CitaDto d){if(!ModelState.IsValid){await Cargar(d.PacienteID);return View(d);}await c.CrearAsync(d);TempData["Mensaje"]="Cita registrada.";return RedirectToAction(nameof(Index));}[HttpGet]public async Task<IActionResult> Edit(int id){var d=await c.ObtenerPorIdAsync(id);if(d==null)return NotFound();await Cargar(d.PacienteID);return View(d);}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Edit(CitaDto d){if(!ModelState.IsValid){await Cargar(d.PacienteID);return View(d);}if(!await c.EditarAsync(d))return NotFound();TempData["Mensaje"]="Cita actualizada.";return RedirectToAction(nameof(Index));}private async Task Cargar(int? id=null)=>ViewBag.Pacientes=new SelectList(await p.ObtenerTodosAsync(),"PacienteID","Nombre",id);}